"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Area, AreaChart, ResponsiveContainer, XAxis } from "recharts";
import { Activity, Apple, ArrowDownRight, ArrowRight, Bell, BookOpen, Check, ChevronDown, CircleHelp, Clock3, Dumbbell, Flame, Footprints, Heart, Home, Leaf, Menu, Moon, MoreHorizontal, Plus, Search, Settings, Sparkles, Sun, Target, TrendingUp, Weight, X, Droplets, CalendarDays } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { calculateEnergy, type EnergyProfile } from "@/lib/calculations/energy";
import { CoachAssistant, type CoachAction } from "@/components/coach-assistant";
import { ProfileOnboarding } from "@/components/profile-onboarding";
import { signOut } from "next-auth/react";

type Page = "Dashboard" | "Habits" | "Workouts" | "Nutrition" | "Weight" | "Planner" | "Insights" | "AI Coach" | "Settings";
type Food = { id: string; date: string; name: string; amount: string; calories: number; protein: number; carbs: number; fats: number };
type Habit = { id: string; title: string; detail: string; iconKey: string; done: boolean; color: string };
type WeightLog = { id: string; date: string; weight: number };
type CalorieDay = { date:string; consumed:number; exercise:number; deficit:number };
const localDay = (date = new Date()) => { const d = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return d.toISOString().slice(0, 10); };
const nav: { name: Page; icon: LucideIcon }[] = [
  { name: "Dashboard", icon: Home }, { name: "Habits", icon: Check }, { name: "Workouts", icon: Dumbbell }, { name: "Nutrition", icon: Apple }, { name: "Weight", icon: Weight }, { name: "Planner", icon: CalendarDays }, { name: "Insights", icon: TrendingUp }, { name: "AI Coach", icon: Sparkles }, { name: "Settings", icon: Settings },
];
const habitIcons: Record<string, LucideIcon> = { sun: Sun, leaf: Leaf, book: BookOpen, water: Droplets, check: Check };
const initialHabits: Habit[] = [
  { id:"habit-sun", title: "Morning sunlight", detail: "10 min · Wellness", iconKey:"sun", done: false, color: "orange" },
  { id:"habit-creatine", title: "Take creatine", detail: "5 g · Supplement", iconKey:"leaf", done: false, color: "lime" },
  { id:"habit-read", title: "Read a little", detail: "20 min · Mind", iconKey:"book", done: false, color: "violet" },
  { id:"habit-water", title: "Drink water", detail: "2.5 L · Health", iconKey:"water", done: false, color: "blue" },
];
const goals = { calories: 2100, protein: 130, carbs: 240, fats: 70 };
const fmt = (n: number) => Math.round(n).toLocaleString();

function useLocalStorageState<T>(key:string,initial:T):[T,React.Dispatch<React.SetStateAction<T>>,boolean]{
  const [value,setValue]=useState<T>(initial);const [loaded,setLoaded]=useState(false);
  useEffect(()=>{try{const stored=localStorage.getItem(key);if(stored!==null)setValue(JSON.parse(stored) as T)}catch{}finally{setLoaded(true)}},[key]);
  useEffect(()=>{const hydrate=()=>{try{const stored=localStorage.getItem(key);if(stored!==null)setValue(JSON.parse(stored) as T)}catch{}};window.addEventListener("pulse-cloud-hydrated",hydrate);return()=>window.removeEventListener("pulse-cloud-hydrated",hydrate)},[key]);
  useEffect(()=>{if(loaded){localStorage.setItem(key,JSON.stringify(value));window.dispatchEvent(new Event("pulse-local-write"))}},[key,value,loaded]);
  return [value,setValue,loaded];
}

export default function PulseHome() {
  const [page, setPage] = useState<Page>("Dashboard");
  const [theme, setTheme] = useState<"dark" | "light">("dark");
  const [ready, setReady] = useState(false);
  const [sheet, setSheet] = useState(false);
  const [foodOpen, setFoodOpen] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [foods, setFoods] = useState<Food[]>([]);
  const [foodsLoaded, setFoodsLoaded] = useState(false);
  const [selectedDate, setSelectedDate] = useState(localDay());
  const [editingFoodId, setEditingFoodId] = useState<string | null>(null);
  const [habits, setHabits] = useLocalStorageState<Habit[]>("pulse-habits",initialHabits);
  const [weights,setWeights]=useLocalStorageState<WeightLog[]>("pulse-weight-logs",[]);
  const [profile,setProfile]=useLocalStorageState<EnergyProfile>("pulse-energy-profile",{age:0,gender:"male",heightCm:0,weightKg:0});
  const [exerciseBurns,setExerciseBurns]=useLocalStorageState<Record<string,number>>("pulse-exercise-burns",{});
  const [calorieTargets,setCalorieTargets]=useLocalStorageState<Record<string,{calories:number;protein:number;carbs:number;fats:number}>>("pulse-calorie-targets",{});
  const [events,setEvents]=useLocalStorageState<PlannerEvent[]>("pulse-events",[]);
  const [habitOpen,setHabitOpen]=useState(false);
  const [habitDraft,setHabitDraft]=useState({title:"",detail:""});
  const [weightOpen,setWeightOpen]=useState(false);
  const [weightDraft,setWeightDraft]=useState({date:localDay(),weight:0,oldDate:""});
  const [plannerAddRequest,setPlannerAddRequest]=useState(0);
  const [workoutAddRequest,setWorkoutAddRequest]=useState(0);
  const [notice, setNotice] = useState("");
  const [cloudReady,setCloudReady]=useState(false);const [cloudError,setCloudError]=useState("");const [cloudRetry,setCloudRetry]=useState(0);
  const cloudRevision=useRef<string|null>(null);const cloudConflict=useRef(false);
  const [food, setFood] = useState<Omit<Food,"id"|"date">>({ name: "", amount: "1 serving", calories: 0, protein: 0, carbs: 0, fats: 0 });
  const dayFoods = useMemo(() => foods.filter((f) => f.date === selectedDate), [foods, selectedDate]);
  const todayFoods = useMemo(()=>foods.filter(f=>f.date===localDay()),[foods]);
  const nutrition = useMemo(() => dayFoods.reduce((a, f) => ({ calories: a.calories + f.calories, protein: a.protein + f.protein, carbs: a.carbs + f.carbs, fats: a.fats + f.fats }), { calories: 0, protein: 0, carbs: 0, fats: 0 }), [dayFoods]);
  const todayNutrition=useMemo(()=>todayFoods.reduce((a,f)=>({calories:a.calories+f.calories,protein:a.protein+f.protein,carbs:a.carbs+f.carbs,fats:a.fats+f.fats}),{calories:0,protein:0,carbs:0,fats:0}),[todayFoods]);
  const calorieDays = useMemo(()=>{const days=new Map<string,number>();foods.forEach(f=>days.set(f.date,(days.get(f.date)??0)+f.calories));return [...days.values()]},[foods]);
  const averageCalories=calorieDays.length?calorieDays.reduce((sum,n)=>sum+n,0)/calorieDays.length:0;
  const calorieHistory=useMemo(()=>[...new Set([...foods.map(f=>f.date),...Object.keys(exerciseBurns)])].sort((a,b)=>b.localeCompare(a)).map(date=>{const consumed=foods.filter(f=>f.date===date).reduce((sum,f)=>sum+f.calories,0);const exercise=exerciseBurns[date]??0;return{date,consumed,exercise,deficit:calculateEnergy(profile,consumed,exercise).deficit}}),[foods,exerciseBurns,profile]);
  const energy=calculateEnergy(profile,nutrition.calories,exerciseBurns[selectedDate]??0);
  const todayEnergy=calculateEnergy(profile,todayNutrition.calories,exerciseBurns[localDay()]??0);
  const upcomingEvents=[...events].filter(x=>x.date>=localDay()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,2);
  useEffect(() => { const stored = localStorage.getItem("pulse-theme") as "dark" | "light" | null; const system = window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark"; setTheme(stored ?? system); setReady(true); }, []);
  useEffect(() => { const load=()=>{try { setFoods(JSON.parse(localStorage.getItem("pulse-food-logs") ?? "[]") as Food[]); } catch { setFoods([]); } finally { setFoodsLoaded(true); }};load();window.addEventListener("pulse-cloud-hydrated",load);return()=>window.removeEventListener("pulse-cloud-hydrated",load) }, []);
  useEffect(() => { if (foodsLoaded) {localStorage.setItem("pulse-food-logs", JSON.stringify(foods));window.dispatchEvent(new Event("pulse-local-write"))} }, [foods, foodsLoaded]);
  useEffect(()=>{const keys=["pulse-habits","pulse-weight-logs","pulse-energy-profile","pulse-exercise-burns","pulse-calorie-targets","pulse-events","pulse-weekly-workouts","pulse-food-logs","pulse-theme"];
    const snapshot=()=>Object.fromEntries(keys.flatMap(key=>{const value=localStorage.getItem(key);if(value===null)return[];try{return[[key,JSON.parse(value)]]}catch{return[]}}));
    const load=async()=>{setCloudError("");cloudConflict.current=false;try{const response=await fetch("/api/state",{cache:"no-store"});if(!response.ok)throw new Error("PULSE could not connect to your private data store.");const result=await response.json() as {data:Record<string,unknown>|null;updatedAt:string|null};cloudRevision.current=result.updatedAt;
      if(result.data){for(const [key,value]of Object.entries(result.data))localStorage.setItem(key,JSON.stringify(value));window.dispatchEvent(new Event("pulse-cloud-hydrated"));}
      else{const saved=await fetch("/api/state",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({data:snapshot(),revision:null}),cache:"no-store"});if(!saved.ok)throw new Error("PULSE could not move this browser’s starter data into your private store.");const savedResult=await saved.json() as {updatedAt:string};cloudRevision.current=savedResult.updatedAt;}
      setCloudReady(true);
    }catch(error){setCloudError(error instanceof Error?error.message:"PULSE could not reach your private data store.");}};
    void load();
  },[cloudRetry]);
  useEffect(()=>{if(!cloudReady)return;let timer:ReturnType<typeof setTimeout>|undefined;let saving=false;let saveAgain=false;const snapshot=()=>{const keys=["pulse-habits","pulse-weight-logs","pulse-energy-profile","pulse-exercise-burns","pulse-calorie-targets","pulse-events","pulse-weekly-workouts","pulse-food-logs","pulse-theme"];return Object.fromEntries(keys.flatMap(key=>{const raw=localStorage.getItem(key);if(raw===null)return[];try{return[[key,JSON.parse(raw)]]}catch{return[]}}))};const push=async()=>{if(cloudConflict.current)return;if(saving){saveAgain=true;return;}saving=true;do{saveAgain=false;try{const response=await fetch("/api/state",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({data:snapshot(),revision:cloudRevision.current}),cache:"no-store"});if(response.status===409){cloudConflict.current=true;setNotice("A newer save exists on another device. Reload PULSE to sync before continuing.");break;}if(!response.ok){setNotice("Sync paused. Your data is still on this device; retry when your connection is back.");break;}const result=await response.json() as {updatedAt:string};cloudRevision.current=result.updatedAt;}catch{setNotice("Sync paused. Your data is still on this device; retry when your connection is back.");break;}}while(saveAgain&&!cloudConflict.current);saving=false;};const save=()=>{if(cloudConflict.current)return;if(timer)clearTimeout(timer);timer=setTimeout(()=>void push(),450);};window.addEventListener("pulse-local-write",save);return()=>{window.removeEventListener("pulse-local-write",save);if(timer)clearTimeout(timer)}},[cloudReady]);
  useEffect(() => { if (ready) { document.documentElement.dataset.theme = theme; localStorage.setItem("pulse-theme", theme);window.dispatchEvent(new Event("pulse-local-write")); } }, [theme, ready]);
  useEffect(()=>{const hydrateTheme=()=>{const stored=localStorage.getItem("pulse-theme");if(stored==="dark"||stored==="light")setTheme(stored)};window.addEventListener("pulse-cloud-hydrated",hydrateTheme);return()=>window.removeEventListener("pulse-cloud-hydrated",hydrateTheme)},[]);
  useEffect(() => { if (!notice) return; const t = setTimeout(() => setNotice(""), 2600); return () => clearTimeout(t); }, [notice]);
  const toggleHabit = (i: number) => setHabits((h) => h.map((item, idx) => idx === i ? { ...item, done: !item.done } : item));
  const addHabit=()=>{if(!habitDraft.title.trim())return;setHabits(h=>[...h,{id:crypto.randomUUID(),title:habitDraft.title.trim(),detail:habitDraft.detail.trim()||"Personal habit",iconKey:"check",done:false,color:"lime"}]);setHabitDraft({title:"",detail:""});setHabitOpen(false);setNotice("Habit added to your list.")};
  const openWeightEntry=(entry?:WeightLog)=>{setWeightDraft(entry?{date:entry.date,weight:entry.weight,oldDate:entry.date}:{date:localDay(),weight:profile.weightKg,oldDate:""});setWeightOpen(true)};
  const saveWeight=(date:string,value:number,oldDate="")=>{if(!Number.isFinite(value)||value<=0)return;setWeights(all=>[...all.filter(x=>x.date!==date&&x.date!==oldDate),{id:crypto.randomUUID(),date,weight:value}].sort((a,b)=>a.date.localeCompare(b.date)));setProfile(p=>({...p,weightKg:value}));setWeightOpen(false);setNotice(`Weight saved. BMR updated to ${fmt(calculateEnergy({...profile,weightKg:value}).bmr)} kcal.`)};
  const openNewFood = () => { setEditingFoodId(null); setFood({ name: "", amount: "1 serving", calories: 0, protein: 0, carbs: 0, fats: 0 }); setFoodOpen(true); };
  const openExistingFood = (entry: Food) => { setEditingFoodId(entry.id); setSelectedDate(entry.date); setFood({name:entry.name,amount:entry.amount,calories:entry.calories,protein:entry.protein,carbs:entry.carbs,fats:entry.fats}); setFoodOpen(true); };
  const saveFood = () => {
    if (!food.name.trim()) { setNotice("Add a food name to continue."); return; }
    const entry: Food = { ...food, id: editingFoodId ?? crypto.randomUUID(), date: selectedDate, name: food.name.trim() };
    setFoods((all) => editingFoodId ? all.map((f) => f.id === editingFoodId ? entry : f) : [...all, entry]);
    setFoodOpen(false); setSheet(false); setPage("Nutrition"); setNotice(editingFoodId ? "Food log updated." : `Food saved for ${selectedDate}.`);
  };
  const act = (label: string) => {
    setSheet(false);
    if (label === "Log food") { openNewFood(); return; }
    if (label === "Complete habit") {
      const next = habits.findIndex((h) => !h.done);
      if (next >= 0) { toggleHabit(next); setNotice(`${habits[next].title} marked complete.`); }
      else setNotice("You’ve completed today’s intentions.");
      return;
    }
    const destinations: Partial<Record<string, Page>> = { "Log workout": "Workouts", "Log weight": "Weight", "Add water": "Dashboard", "Add event": "Planner" };
    const destination = destinations[label];
    if (destination) setPage(destination);
    if(label==="Log weight"){openWeightEntry();return;}
    if(label==="Add event"){setPlannerAddRequest(v=>v+1);return;}
    if(label==="Log workout"){setWorkoutAddRequest(v=>v+1);return;}
    setNotice(label === "Add water" ? "Water tracking is ready for the next phase." : `${label} opened.`);
  };
  const applyCoachAction = (action: CoachAction) => {
    if (action.type === "navigate") { setPage(action.page as Page); return; }
    if (action.type === "add_habit") { setHabits(h => [...h, {id:crypto.randomUUID(),title:action.title,detail:action.detail||"Personal habit",iconKey:"check",done:false,color:"lime"}]); return; }
    if (action.type === "add_event") { setEvents(all => [...all, {id:crypto.randomUUID(),title:action.title,date:action.date,time:action.time,category:action.category}]); setPage("Planner"); return; }
    if (action.type === "add_food") { setFoods(all => [...all, {id:crypto.randomUUID(),date:action.date,name:action.name,amount:action.amount,calories:action.calories,protein:action.protein,carbs:action.carbs,fats:action.fats}]); setSelectedDate(action.date); setPage("Nutrition"); return; }
    if (action.type === "log_weight") { saveWeight(action.date,action.weight); setPage("Weight"); return; }
    if (action.type === "exercise_burn") { setExerciseBurns(all => ({...all,[action.date]:action.calories})); setSelectedDate(action.date); setPage("Nutrition"); }
  };
  if(!cloudReady)return <main className="sync-gate"><div className="sync-mark"><Activity size={23}/></div><span className="eyebrow">PRIVATE PULSE DATA</span><h1>{cloudError?"Your secure store needs attention":"Opening your personal space…"}</h1><p>{cloudError||"Loading your latest logs securely."}</p>{cloudError&&<button className="primary-btn" onClick={()=>setCloudRetry(v=>v+1)}>Retry connection <ArrowRight size={15}/></button>}</main>;
  if(!profile.age||!profile.heightCm||!profile.weightKg)return <ProfileOnboarding onComplete={setProfile}/>;
  return <main className="app-shell">
    <aside className={`sidebar ${mobileMenuOpen ? "mobile-open" : ""}`}>
      <a className="brand" href="#home" onClick={(e) => { e.preventDefault(); setPage("Dashboard"); setMobileMenuOpen(false); }}><span className="brand-mark"><Activity size={18} strokeWidth={2.5}/></span><span>PULSE</span><span className="brand-dot"/><button className="drawer-close" aria-label="Close menu" onClick={(e)=>{e.preventDefault();setMobileMenuOpen(false);}}><X size={18}/></button></a>
      <span className="nav-label">YOUR TRACKING</span><nav className="side-nav">{nav.map(({name, icon: Icon}) => <button key={name} className={`nav-item ${page === name ? "selected" : ""}`} onClick={() => {setPage(name);setMobileMenuOpen(false);}}><Icon size={17}/><span>{name}</span>{name === "AI Coach" && <span className="new-dot"/>}{name === "Dashboard" && <span className="nav-indicator"/>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="streak-mini"><span className="streak-icon"><Flame size={16}/></span><div><strong>Your personal dashboard</strong><small>Built around your routine</small></div><ArrowRight size={15}/></div><div className="side-user"><div className="avatar small">M</div><div><strong>Madhvendra Singh</strong><small>Personal space</small></div></div></div>
    </aside>
    <section className="main-area">
      <header className="topbar"><button aria-label="Open menu" aria-expanded={mobileMenuOpen} className="mobile-menu" onClick={() => setMobileMenuOpen(true)}><Menu size={19}/></button><div className="crumb"><span>My PULSE</span><span className="slash">/</span><strong>{page}</strong></div><div className="top-actions"><span className="date-pill"><CalendarDays size={14}/> {new Date().toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short"})}</span><button aria-label="Switch theme" className="icon-btn theme-btn" onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>{theme === "dark" ? <Sun size={17}/> : <Moon size={17}/>}</button><div className="top-avatar">M</div></div></header>
      {mobileMenuOpen && <button className="drawer-scrim" aria-label="Close navigation" onClick={()=>setMobileMenuOpen(false)}/>}
      <div className="content-wrap"><AnimatePresence mode="wait"><motion.div key={page} className="page-content" initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}} transition={{duration:.18}}>
      {page === "Dashboard" ? <>
        <div className="welcome-row"><div><div className="eyebrow"><span className="live-dot"/> {new Date().toLocaleDateString("en-IN",{weekday:"long",month:"long",day:"numeric",year:"numeric"}).toUpperCase()}</div><h1>Good morning, Madhvendra <span className="wave">✳</span></h1><p className="subtitle">A little progress, every day. You’re finding your rhythm.</p></div><button className="primary-btn" onClick={() => setSheet(true)}><Plus size={17}/> Quick log</button></div>
        <section className="hero-card"><div className="hero-glow"/><div className="hero-left"><div className="hero-topline"><span className="hero-chip"><Sparkles size={13}/> YOUR DAILY PULSE</span></div><h2>Make today<br/><span>count.</span></h2><p>Steady habits. Useful numbers.<br/>Your routine, your pace.</p><button className="hero-link" onClick={() => setPage("Insights")}>See your progress <ArrowRight size={15}/></button></div><div className="ring-wrap"><div className="ring" style={{background:`conic-gradient(#ff9065 0deg ${habits.length?habits.filter(h=>h.done).length/habits.length*360:0}deg,rgba(255,255,255,.1) 0deg 360deg)`}}><div className="ring-inner"><strong>{habits.length?Math.round(habits.filter(h=>h.done).length/habits.length*100):0}<span>%</span></strong><small>HABITS TODAY</small></div></div><div className="ring-caption"><span className="ring-caption-dot"/> {habits.filter(h=>h.done).length} of {habits.length} habits done</div></div><div className="hero-orbit orbit-one"/><div className="hero-orbit orbit-two"/></section>
        <div className="section-heading"><div><h2>Your day, in focus</h2><p>A quick read on how you’re doing.</p></div><button className="text-btn" onClick={() => setPage("Insights")}>View insights <ArrowRight size={14}/></button></div>
        <div className="stats-grid">
          <article className="stat-card calorie-card"><div className="stat-head"><span>Average daily calories</span><span className="stat-icon coral"><Apple size={16}/></span></div><div className="stat-value">{fmt(averageCalories)} <small>kcal</small></div><div className="stat-sub">{calorieDays.length?`average across ${calorieDays.length} logged day${calorieDays.length===1?"":"s"}`:"Log meals to build your daily average"}</div><div className="bar-track"><div className="bar-fill coral-fill" style={{width:`${Math.min(100,averageCalories / todayEnergy.sedentaryTdee * 100)}%`}}/></div><div className="macro-line"><span>Today <b>{fmt(todayNutrition.calories)} kcal</b></span><button className="tiny-link" onClick={()=>setPage("Nutrition")}>View days →</button></div></article>
          <article className="stat-card"><div className="stat-head"><span>Habits</span><span className="stat-icon lime"><Check size={16}/></span></div><div className="stat-value">{habits.filter(h=>h.done).length}<small> / {habits.length}</small></div><div className="stat-sub">intentions completed</div><div className="mini-bars">{habits.map((h,i)=><i key={h.id} className={h.done?"today":""} style={{height:h.done?"100%":"34%"}}/>)}</div><div className="foot-note"><span>{habits.length?Math.round(habits.filter(h=>h.done).length/habits.length*100):0}% complete</span><span>today</span></div></article>
          <article className="stat-card"><div className="stat-head"><span>Today’s daily burn</span><span className="stat-icon violet"><Flame size={16}/></span></div><div className="stat-value">{fmt(todayEnergy.totalBurn)}<small> kcal</small></div><div className="stat-sub">{fmt(todayEnergy.sedentaryTdee)} base + {fmt(todayEnergy.exerciseBurn)} exercise</div><div className="workout-progress"><div className="workout-icon"><Activity size={16}/></div><div><b>Today’s deficit</b><small>{fmt(todayEnergy.deficit)} kcal estimated</small></div><button aria-label="Update exercise burn" onClick={() => {setSelectedDate(localDay());setPage("Nutrition")}}><ArrowRight size={15}/></button></div></article>
          <article className="stat-card weight-card"><div className="stat-head"><span>Current weight</span><span className="stat-icon blue"><Weight size={16}/></span></div><div className="stat-value">{profile.weightKg.toFixed(1)}<small> kg</small></div><div className="stat-sub">Mifflin–St Jeor BMR updates with weight</div><div className="mini-bars weight-bars">{weights.slice(-7).map((w,i)=><i key={w.id} className={i===weights.slice(-7).length-1?"today":""} style={{height:`${Math.max(20,Math.min(100,w.weight/profile.weightKg*80))}%`}}/>)}{weights.length===0&&<span>Log weight to start a personal trend</span>}</div><button className="tiny-link" onClick={()=>openWeightEntry()}>Log weight <ArrowRight size={13}/></button></article>
        </div>
        <div className="lower-grid"><section className="panel habit-panel"><div className="panel-heading"><div><h3>Daily intentions</h3><p>Your personal habits.</p></div><button className="tiny-link" onClick={() => setPage("Habits")}>All habits <ArrowRight size={13}/></button></div><div className="habit-list">{habits.map((h,i)=>{const Icon=habitIcons[h.iconKey]??Check;return <button className={`habit-row ${h.done?"is-done":""}`} key={h.id} onClick={()=>toggleHabit(i)}><span className={`habit-icon ${h.color}`}><Icon size={16}/></span><span className="habit-copy"><strong>{h.title}</strong><small>{h.detail}</small></span><span className={`check-circle ${h.done?"checked":""}`}>{h.done&&<Check size={13}/>}</span></button>})}</div><button className="add-habit" onClick={()=>setHabitOpen(true)}><Plus size={14}/> Add an intention</button></section>
          <section className="panel side-panel"><div className="panel-heading"><div><h3>Coming up</h3><p>Your personal reminders.</p></div><button className="icon-btn small-btn" aria-label="Planner" onClick={()=>setPage("Planner")}><ArrowRight size={15}/></button></div>{upcomingEvents.length?upcomingEvents.map(event=><div className="event-card" key={event.id}><div className="event-date"><strong>{new Date(`${event.date}T12:00:00`).getDate()}</strong><small>{new Date(`${event.date}T12:00:00`).toLocaleDateString("en-IN",{month:"short"}).toUpperCase()}</small></div><div className="event-info"><strong>{event.title}</strong><span><Clock3 size={12}/> {event.time} <span className="event-dot"/> {event.category}</span></div></div>):<div className="empty-state compact-empty"><span><CalendarDays size={16}/></span><b>No upcoming events</b><p>Add a reminder whenever you need one.</p></div>}<button className="calendar-link" onClick={()=>setPage("Planner")}>Open planner <ArrowRight size={14}/></button></section></div>
        <div className="insight-strip"><span className="insight-spark"><Sparkles size={16}/></span><div><strong>Your energy baseline</strong><p>Mifflin–St Jeor estimates a {fmt(todayEnergy.sedentaryTdee)} kcal sedentary TDEE. Add food and exercise logs to see your actual daily balance.</p><small>BASED ON YOUR PROFILE · {profile.weightKg.toFixed(1)} KG</small></div><button aria-label="Open AI Coach calculator" onClick={()=>setPage("AI Coach")}><ArrowRight size={16}/></button></div>
      </> : <ModulePage page={page} setPage={setPage} setTheme={setTheme} theme={theme} foods={dayFoods} nutrition={nutrition} selectedDate={selectedDate} setSelectedDate={setSelectedDate} editFood={openExistingFood} habits={habits} toggleHabit={toggleHabit} openQuick={()=>setSheet(true)} openFood={openNewFood} openHabit={()=>setHabitOpen(true)} weightLogs={weights} currentWeight={profile.weightKg} profile={profile} onSaveWeight={saveWeight} onEditWeight={openWeightEntry} exerciseBurn={exerciseBurns[selectedDate]??0} setExerciseBurn={(n:number)=>setExerciseBurns(all=>({...all,[selectedDate]:n}))} energy={energy} averageCalories={averageCalories} calorieHistory={calorieHistory} calorieTarget={calorieTargets[selectedDate]} onWeightLog={()=>openWeightEntry()} events={events} setEvents={setEvents} plannerAddRequest={plannerAddRequest} onAddEvent={()=>setPlannerAddRequest(v=>v+1)} workoutAddRequest={workoutAddRequest} onAddWorkout={()=>setWorkoutAddRequest(v=>v+1)} onUseCoach={(date,burn,target)=>{setSelectedDate(date);setExerciseBurns(all=>({...all,[date]:burn}));setCalorieTargets(all=>({...all,[date]:target}));setPage("Nutrition")}} coachContext={{date:selectedDate,profile,day:{...nutrition,...energy},averageCalories,habits:habits.map(h=>h.title),upcomingEvents:events.slice(0,6).map(e=>({title:e.title,date:e.date,time:e.time}))}} onCoachAction={applyCoachAction}/>}
      </motion.div></AnimatePresence><footer className="footer-note">Your data belongs to you <span>·</span> PULSE is a personal space</footer></div>
      <nav className="mobile-nav">{[{n:"Dashboard" as Page,i:Home},{n:"Planner" as Page,i:CalendarDays}].map(({n,i:Icon})=><button key={n} className={page===n?"active":""} onClick={()=>setPage(n)}><Icon size={20}/><span>{n}</span></button>)}<button className="mobile-add" onClick={()=>setSheet(true)} aria-label="Quick add"><Plus size={22}/></button>{[{n:"Insights" as Page,i:TrendingUp},{n:"Settings" as Page,i:CircleHelp}].map(({n,i:Icon})=><button key={n} className={page===n?"active":""} onClick={()=>setPage(n)}><Icon size={20}/><span>{n==="Settings"?"Profile":n}</span></button>)}</nav>
    </section>

    <AnimatePresence>{sheet&&<><motion.button className="scrim" aria-label="Close quick actions" onClick={()=>setSheet(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.section className="quick-sheet" role="dialog" aria-modal="true" aria-labelledby="quick-title" initial={{y:"100%"}} animate={{y:0}} exit={{y:"100%"}} transition={{type:"spring",damping:30,stiffness:300}}><div className="sheet-grabber"/><div className="sheet-head"><div><span className="eyebrow">KEEP YOUR MOMENTUM</span><h2 id="quick-title">What would you like to log?</h2></div><button className="icon-btn" onClick={()=>setSheet(false)} aria-label="Close"><X size={18}/></button></div><div className="quick-grid">{[{label:"Log food",icon:Apple,color:"coral"},{label:"Log workout",icon:Dumbbell,color:"violet"},{label:"Complete habit",icon:Check,color:"lime"},{label:"Log weight",icon:Weight,color:"blue"},{label:"Add water",icon:Droplets,color:"blue"},{label:"Add event",icon:CalendarDays,color:"orange"}].map(({label,icon:Icon,color})=><button key={label} className="quick-action" onClick={()=>act(label)}><span className={`quick-icon ${color}`}><Icon size={18}/></span><span>{label}</span><ArrowRight size={14}/></button>)}</div><p className="sheet-foot"><Sparkles size={13}/> Quick actions stay simple. AI is always optional.</p></motion.section></>}</AnimatePresence>
    <AnimatePresence>{foodOpen&&<><motion.button className="scrim" aria-label="Close food entry" onClick={()=>setFoodOpen(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.section className="food-dialog" role="dialog" aria-modal="true" aria-labelledby="food-title" initial={{opacity:0,scale:.96,y:12}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:.98}}><div className="dialog-head"><div><span className="eyebrow">NUTRITION · MANUAL ENTRY</span><h2 id="food-title">{editingFoodId ? "Edit food log" : "Add to your food log"}</h2><p>Choose any date and adjust the values at any time.</p></div><button className="icon-btn" onClick={()=>setFoodOpen(false)} aria-label="Close"><X size={18}/></button></div><label className="field-label">Log date<input type="date" value={selectedDate} onChange={e=>setSelectedDate(e.target.value)}/></label><label className="field-label">Food or meal<input autoFocus value={food.name} placeholder="e.g. Paneer bhurji" onChange={e=>setFood({...food,name:e.target.value})}/></label><label className="field-label">Serving size<input value={food.amount} onChange={e=>setFood({...food,amount:e.target.value})}/></label><div className="nutrition-inputs">{([{key:"calories",label:"Calories",unit:"kcal"},{key:"protein",label:"Protein",unit:"g"},{key:"carbs",label:"Carbs",unit:"g"},{key:"fats",label:"Fats",unit:"g"}] as const).map(({key,label,unit})=><label className="field-label" key={key}>{label}<span className="input-unit"><input type="number" min="0" value={food[key]} onChange={e=>setFood({...food,[key]:Math.max(0,Number(e.target.value))})}/><small>{unit}</small></span></label>)}</div><div className="manual-note"><span><Heart size={14}/></span><p>Nutrition values are saved in this browser and can be edited later.</p></div><div className="dialog-actions"><button className="secondary-btn" onClick={()=>setFoodOpen(false)}>Cancel</button><button className="primary-btn" onClick={saveFood}>{editingFoodId ? "Update entry" : "Save food"} <ArrowRight size={15}/></button></div></motion.section></>}</AnimatePresence>
    <AnimatePresence>{habitOpen&&<><motion.button className="scrim" aria-label="Close habit form" onClick={()=>setHabitOpen(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.section className="food-dialog" role="dialog" aria-modal="true" aria-labelledby="habit-form-title" initial={{opacity:0,scale:.97,y:10}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:.98}}><div className="dialog-head"><div><span className="eyebrow">YOUR ROUTINE</span><h2 id="habit-form-title">Add a daily habit</h2><p>Create a personal intention and check it off each day.</p></div><button className="icon-btn" aria-label="Close" onClick={()=>setHabitOpen(false)}><X size={18}/></button></div><label className="field-label">Habit name<input autoFocus value={habitDraft.title} placeholder="e.g. Walk after lunch" onChange={e=>setHabitDraft({...habitDraft,title:e.target.value})}/></label><label className="field-label">Target or category<input value={habitDraft.detail} placeholder="e.g. 20 minutes · Movement" onChange={e=>setHabitDraft({...habitDraft,detail:e.target.value})}/></label><div className="dialog-actions"><button className="secondary-btn" onClick={()=>setHabitOpen(false)}>Cancel</button><button className="primary-btn" onClick={addHabit}>Add habit <ArrowRight size={15}/></button></div></motion.section></>}</AnimatePresence>
    <AnimatePresence>{weightOpen&&<><motion.button className="scrim" aria-label="Close weight log" onClick={()=>setWeightOpen(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.section className="food-dialog" role="dialog" aria-modal="true" aria-labelledby="weight-title" initial={{opacity:0,scale:.97,y:10}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:.98}}><div className="dialog-head"><div><span className="eyebrow">WEIGHT · PERSONAL LOG</span><h2 id="weight-title">Log your weight</h2><p>Your BMR and sedentary TDEE update from this value.</p></div><button className="icon-btn" aria-label="Close" onClick={()=>setWeightOpen(false)}><X size={18}/></button></div><label className="field-label">Log date<input type="date" value={weightDraft.date} onChange={e=>setWeightDraft({...weightDraft,date:e.target.value})}/></label><label className="field-label">Weight in kilograms<input type="number" min="1" step="0.1" value={weightDraft.weight} onChange={e=>setWeightDraft({...weightDraft,weight:Number(e.target.value)})}/></label><div className="manual-note"><span><Activity size={14}/></span><p>Current profile weight: {profile.weightKg.toFixed(1)} kg · BMR: {fmt(calculateEnergy(profile).bmr)} kcal.</p></div><div className="dialog-actions"><button className="secondary-btn" onClick={()=>setWeightOpen(false)}>Cancel</button><button className="primary-btn" onClick={()=>saveWeight(weightDraft.date,weightDraft.weight,weightDraft.oldDate)}>Save weight <ArrowRight size={15}/></button></div></motion.section></>}</AnimatePresence>
    <AnimatePresence>{notice&&<motion.div className="toast" initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}}><Check size={15}/>{notice}</motion.div>}</AnimatePresence>
  </main>;
}

function ModulePage({page,setPage,setTheme,theme,foods,nutrition,selectedDate,setSelectedDate,editFood,habits,toggleHabit,openQuick,openFood,openHabit,weightLogs,currentWeight,profile,onSaveWeight,onEditWeight,exerciseBurn,setExerciseBurn,energy,averageCalories,calorieHistory,calorieTarget,onWeightLog,events,setEvents,plannerAddRequest,onAddEvent,workoutAddRequest,onAddWorkout,onUseCoach,coachContext,onCoachAction}:{page:Page;setPage:(p:Page)=>void;setTheme:(t:"dark"|"light")=>void;theme:"dark"|"light";foods:Food[];nutrition:{calories:number;protein:number;carbs:number;fats:number};selectedDate:string;setSelectedDate:(d:string)=>void;editFood:(f:Food)=>void;habits:Habit[];toggleHabit:(i:number)=>void;openQuick:()=>void;openFood:()=>void;openHabit:()=>void;weightLogs:WeightLog[];currentWeight:number;profile:EnergyProfile;onSaveWeight:(date:string,value:number,oldDate?:string)=>void;onEditWeight:(entry?:WeightLog)=>void;exerciseBurn:number;setExerciseBurn:(n:number)=>void;energy:ReturnType<typeof calculateEnergy>;averageCalories:number;calorieHistory:CalorieDay[];calorieTarget?:{calories:number;protein:number;carbs:number;fats:number};onWeightLog:()=>void;events:PlannerEvent[];setEvents:React.Dispatch<React.SetStateAction<PlannerEvent[]>>;plannerAddRequest:number;onAddEvent:()=>void;workoutAddRequest:number;onAddWorkout:()=>void;onUseCoach:(date:string,burn:number,target:{calories:number;protein:number;carbs:number;fats:number})=>void;coachContext:Record<string,unknown>;onCoachAction:(action:CoachAction)=>void}) {
  const copy:Record<Page,{eyebrow:string;title:string;desc:string;icon:LucideIcon;action:string}>={
    Dashboard:{eyebrow:"HOME",title:"Your day",desc:"A little progress, every day.",icon:Home,action:"Quick log"},Habits:{eyebrow:"CONSISTENCY",title:"Daily intentions",desc:"Build a rhythm that feels like yours.",icon:Check,action:"Add intention"},Workouts:{eyebrow:"MOVEMENT",title:"Train with intention",desc:"A plan that grows with you.",icon:Dumbbell,action:"Log workout"},Nutrition:{eyebrow:"NOURISHMENT",title:"Food, without the fuss",desc:"Simple, flexible nutrition tracking.",icon:Apple,action:"Log food"},Weight:{eyebrow:"YOUR TREND",title:"Progress takes time",desc:"Look at the trend, not a single day.",icon:Weight,action:"Log weight"},Planner:{eyebrow:"MAKE ROOM",title:"Your planner",desc:"A little structure for the things that matter.",icon:CalendarDays,action:"Add event"},Insights:{eyebrow:"REFLECTION",title:"Notice your progress",desc:"Patterns become clearer with consistency.",icon:TrendingUp,action:"Explore"},"AI Coach":{eyebrow:"OPTIONAL AI COACH",title:"A thoughtful nudge, when you want one.",desc:"AI guidance is optional. Your tracking always works without it.",icon:Sparkles,action:"Ask a question"},Settings:{eyebrow:"YOUR SPACE",title:"Make PULSE yours",desc:"Preferences and privacy, all in one place.",icon:Settings,action:"Manage settings"}};
  const info=copy[page], Icon=info.icon;
  const click=()=>{if(page==="Nutrition")openFood();else if(page==="Habits")openHabit();else if(page==="Weight")onWeightLog();else if(page==="Planner")onAddEvent();else if(page==="Workouts")onAddWorkout();else openQuick();};
  return <div className="module-page">{page==="Nutrition"&&calorieTarget&&<section className="panel coach-target-strip"><div><span className="eyebrow">COACH TARGET · {selectedDate}</span><strong>{calorieTarget.calories.toLocaleString()} kcal</strong><small>Protein {calorieTarget.protein}g · Carbs {calorieTarget.carbs}g · Fat {calorieTarget.fats}g</small></div><button className="tiny-link" onClick={()=>setPage("AI Coach")}>Adjust in AI Coach <ArrowRight size={13}/></button></section>}<div className="eyebrow"><span className="live-dot"/>{info.eyebrow}</div><div className="module-title-row"><div><h1>{info.title}</h1><p className="subtitle">{info.desc}</p></div><button className="primary-btn" onClick={click}><Plus size={16}/>{info.action}</button></div>
    {page==="Nutrition"?<><div className="date-toolbar"><label>Viewing logs for <input aria-label="Choose log date" type="date" value={selectedDate} onChange={e=>setSelectedDate(e.target.value)}/></label><button className="tiny-link" onClick={()=>setSelectedDate(localDay())}>Today</button></div><div className="nutrition-summary"><div><span>Calories consumed</span><strong>{fmt(nutrition.calories)} <small>kcal</small></strong><p>Daily average: {fmt(averageCalories)} kcal across logged days</p></div><div className="macro-cards">{[["Protein",nutrition.protein,"g"],["Carbs",nutrition.carbs,"g"],["Fats",nutrition.fats,"g"]].map(([n,v,u])=><span key={String(n)}>{n}<b>{v}{u}</b></span>)}</div></div><section className="panel module-panel"><div className="panel-heading"><div><h3>Exercise calories burned</h3><p>Enter exercise calories separately from your sedentary base burn.</p></div><span className="demo-tag">{selectedDate}</span></div><div className="burn-input"><label>Exercise burn (kcal)<input type="number" min="0" step="10" value={exerciseBurn} onChange={e=>setExerciseBurn(Math.max(0,Number(e.target.value)))}/></label><small>Total daily burn = sedentary TDEE + exercise burn</small></div></section><section className="panel module-panel energy-panel"><div className="panel-heading"><div><h3>Daily energy calculation</h3><p>Mifflin–St Jeor · male · age {profile.age} · {profile.heightCm} cm · {currentWeight.toFixed(1)} kg</p></div><span className="demo-tag">{selectedDate}</span></div><div className="energy-breakdown">{[["BMR",energy.bmr,"kcal"],["Sedentary TDEE · BMR × 1.2",energy.sedentaryTdee,"kcal"],["Exercise burn",energy.exerciseBurn,"kcal"],["Total daily burn",energy.totalBurn,"kcal"],["Calories consumed",nutrition.calories,"kcal"],["Calorie deficit",energy.deficit,"kcal"],["Estimated fat loss",energy.fatLossGrams,"g / day"],["Fat loss estimate",energy.weeklyFatLossKg,"kg / week"]].map(([label,value,unit])=><div key={String(label)} className={label==="Total daily burn"||label==="Calorie deficit"?"energy-highlight":""}><span>{label}</span><b>{typeof value==="number"?value.toLocaleString("en-IN",{maximumFractionDigits:1}):value} {unit}</b></div>)}</div><p className="module-disclaimer">Estimates only. The 7,700 kcal/kg conversion is approximate; daily scale weight naturally fluctuates.</p></section><section className="panel module-panel"><div className="panel-heading"><div><h3>Food entries</h3><p>{foods.length ? `${foods.length} item${foods.length===1?"":"s"} logged on ${selectedDate}` : "Nothing logged for this day. Add an entry whenever you need."}</p></div><span className="demo-tag">YOUR LOG</span></div>{foods.length?foods.map((f)=><div className="food-row" key={f.id}><span className="food-bullet"><Apple size={15}/></span><div><b>{f.name}</b><small>{f.amount} · P {f.protein}g · C {f.carbs}g · F {f.fats}g</small></div><strong>{f.calories} <small>kcal</small></strong><button className="secondary-btn" onClick={()=>editFood(f)}>Edit</button></div>):<Empty message="Your food log starts with one small entry." icon={Apple}/>}</section><p className="module-disclaimer">Entries are stored in this browser and can be added or edited for past dates.</p></>:null}
    {page==="Nutrition"&&<section className="panel module-panel calorie-history"><div className="panel-heading"><div><h3>Day-by-day calorie history</h3><p>Select a past day to review its intake, burn, and deficit.</p></div><span className="demo-tag">{calorieHistory.length} LOGGED DAYS</span></div>{calorieHistory.length?calorieHistory.map(row=><button className={`calorie-day-row ${selectedDate===row.date?"selected":""}`} key={row.date} onClick={()=>setSelectedDate(row.date)}><span>{new Date(`${row.date}T12:00:00`).toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short",year:"numeric"})}</span><b>{fmt(row.consumed)} kcal eaten</b><small>{fmt(row.exercise)} kcal exercise</small><strong>{fmt(row.deficit)} kcal deficit</strong></button>):<Empty message="As you log meals or exercise burn, each day will appear here." icon={Activity}/>}</section>}
    {page==="Habits"?<section className="panel module-panel"><div className="panel-heading"><div><h3>Today’s intentions</h3><p>Tap a circle to update your day.</p></div><span className="demo-tag">YOUR HABITS</span></div>{habits.map((h,i)=>{const I=habitIcons[h.iconKey]??Check;return <button className={`habit-row ${h.done?"is-done":""}`} key={h.id} onClick={()=>toggleHabit(i)}><span className={`habit-icon ${h.color}`}><I size={16}/></span><span className="habit-copy"><strong>{h.title}</strong><small>{h.detail}</small></span><span className={`check-circle ${h.done?"checked":""}`}>{h.done&&<Check size={13}/>}</span></button>})}<button className="add-habit" onClick={openHabit}><Plus size={14}/> Add a habit</button></section>:null}
    {page==="Workouts"?<WeeklyWorkoutPlanner addRequest={workoutAddRequest}/>:null}
    {page==="Weight"?<WeightTracker entries={weightLogs} currentWeight={currentWeight} onNew={onWeightLog} onEdit={onEditWeight}/>:null}
    {page==="Planner"?<PlannerManager events={events} setEvents={setEvents} addRequest={plannerAddRequest}/>:null}
    {page==="Insights"?<><div className="insight-grid"><article className="insight-card"><span className="stat-icon coral"><Apple size={16}/></span><small>AVERAGE DAILY INTAKE</small><strong>{fmt(averageCalories)} kcal</strong><p>Average across days where you have food logs.</p></article><article className="insight-card"><span className="stat-icon blue"><Activity size={16}/></span><small>YOUR CURRENT BMR</small><strong>{fmt(calculateEnergy(profile).bmr)} kcal</strong><p>Updates when you log a new weight.</p></article><article className="insight-card"><span className="stat-icon lime"><Flame size={16}/></span><small>SELECTED DAY DEFICIT</small><strong>{fmt(energy.deficit)} kcal</strong><p>From selected date’s food and exercise logs.</p></article></div><section className="insight-strip"><span className="insight-spark"><Sparkles size={16}/></span><div><strong>Keep logging consistently</strong><p>Daily averages become more useful as you record more days of food and exercise.</p><small>CALCULATED FROM YOUR LOCAL LOGS</small></div></section></>:null}
    {page==="AI Coach"?<><CoachAssistant context={coachContext} onApprove={onCoachAction}/><CoachCalculator profile={profile} date={selectedDate} caloriesConsumed={nutrition.calories} onApply={onUseCoach} goWorkouts={()=>setPage("Workouts")}/></>:null}
    {page==="Settings"?<div className="settings-stack"><section className="panel setting-row"><div><b>Appearance</b><small>Choose a comfortable theme.</small></div><button className="theme-select" onClick={()=>setTheme(theme === "light" ? "dark" : "light")}>{theme === "light" ? <Sun size={14}/> : <Moon size={14}/>} {theme === "light" ? "Porcelain" : "Obsidian"} <ChevronDown size={14}/></button></section><section className="panel setting-row"><div><b>Food preferences</b><small>Default suggestions avoid meat and fish.</small></div><span className="pref-tag">Eggetarian</span></section><section className="panel setting-row"><div><b>Privacy by default</b><small>Your tracking data syncs to your owner-only Atlas record.</small></div><span className="privacy-tag"><Heart size={13}/> Private cloud</span></section><section className="panel setting-row"><div><b>Owner session</b><small>End this private session on this device.</small></div><button className="secondary-btn" onClick={()=>signOut({callbackUrl:"/login"})}>Sign out</button></section><div className="module-disclaimer">PULSE syncs edits to Atlas after a short delay. Keep a separate backup of important personal records.</div></div>:null}
    </div>;
}
function Empty({message,icon:Icon}:{message:string;icon:LucideIcon}) { return <div className="empty-state"><span><Icon size={19}/></span><b>Nothing here just yet</b><p>{message}</p></div>; }

type WeeklyExercise={id:string;name:string;sets:number;reps:string;mediaUrl:string;actualSets:{reps:string;weight:string}[]};
const weekKeys=["sun","mon","tue","wed","thu","fri","sat"] as const;
const dayNames=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
function WeeklyWorkoutPlanner({addRequest}:{addRequest:number}){
  const todayKey=weekKeys[new Date().getDay()];
  const [day,setDay]=useState<string>(todayKey);
  const [plans,setPlans,loaded]=useLocalStorageState<Record<string,WeeklyExercise[]>>("pulse-weekly-workouts",{});
  const [dialog,setDialog]=useState(false);const [editing,setEditing]=useState<string|null>(null);
  const empty={name:"",sets:3,reps:"8–12",mediaUrl:""};const [draft,setDraft]=useState(empty);
  const items=plans[day]??[];
  const openNew=()=>{setEditing(null);setDraft(empty);setDialog(true)};
  useEffect(()=>{if(addRequest>0)openNew()},[addRequest]);
  const openEdit=(item:WeeklyExercise)=>{setEditing(item.id);setDraft({name:item.name,sets:item.sets,reps:item.reps,mediaUrl:item.mediaUrl});setDialog(true)};
  const save=()=>{if(!draft.name.trim())return;const old=items.find(x=>x.id===editing);const entry:WeeklyExercise={...draft,id:editing??crypto.randomUUID(),name:draft.name.trim(),sets:Math.max(1,Math.min(20,Number(draft.sets)||1)),reps:draft.reps.trim()||"8–12",mediaUrl:draft.mediaUrl.trim(),actualSets:old?.actualSets?.slice(0,Math.max(1,Number(draft.sets)||1))??[]};while(entry.actualSets.length<entry.sets)entry.actualSets.push({reps:"",weight:""});setPlans(all=>({...all,[day]:editing?(all[day]??[]).map(x=>x.id===editing?entry:x):[...(all[day]??[]),entry]}));setDialog(false)};
  const updateSet=(item:WeeklyExercise,index:number,key:"reps"|"weight",value:string)=>setPlans(all=>({...all,[day]:(all[day]??[]).map(ex=>ex.id===item.id?{...ex,actualSets:ex.actualSets.map((set,i)=>i===index?{...set,[key]:value}:set)}:ex)}));
  const remove=(id:string)=>setPlans(all=>({...all,[day]:(all[day]??[]).filter(x=>x.id!==id)}));
  return <><section className="panel module-panel workout-planner"><div className="panel-heading"><div><h3>Repeatable weekly plan</h3><p>Choose a weekday. The same plan repeats each week.</p></div><span className="demo-tag">NO DATES</span></div><div className="weekday-strip weekly-strip">{weekKeys.map((key,i)=><button key={key} aria-label={dayNames[i]} className={`weekday ${day===key?"selected":""}`} onClick={()=>setDay(key)}><small>{dayNames[i].slice(0,3).toUpperCase()}</small><b>{dayNames[i].slice(0,3)}</b></button>)}</div><div className="panel-heading workout-day-heading"><div><h3>{dayNames[weekKeys.indexOf(day as typeof weekKeys[number])]}</h3><p>{items.length?`${items.length} movements in this weekly plan`:"No movements added for this weekday yet."}</p></div><button className="primary-btn" onClick={openNew}><Plus size={15}/> Add exercise</button></div>{items.length===0?<Empty message="Add an exercise to this weekday. It will stay in your weekly template." icon={Dumbbell}/>:items.map((item,index)=><article className="weekly-exercise" key={item.id}><div className="exercise-card"><span className="exercise-number">{String(index+1).padStart(2,"0")}</span><div className="exercise-main"><b>{item.name}</b><small>{item.sets} sets · target {item.reps} reps</small>{item.mediaUrl&&<a href={item.mediaUrl} target="_blank" rel="noreferrer" className="exercise-media-link"><ArrowRight size={13}/> Open exercise guide</a>}</div>{item.mediaUrl&&(/\.(gif|png|jpe?g|webp)(\?.*)?$/i.test(item.mediaUrl))&&<a className="exercise-preview" href={item.mediaUrl} target="_blank" rel="noreferrer"><img src={item.mediaUrl} alt={`${item.name} exercise demo`} loading="lazy"/></a>}<button className="secondary-btn" onClick={()=>openEdit(item)}>Edit</button><button className="delete-btn" aria-label={`Remove ${item.name}`} onClick={()=>remove(item.id)}><X size={15}/></button></div><div className="set-tracker"><span className="set-tracker-title">Log your sets</span>{Array.from({length:item.sets},(_,i)=><div className="set-input-row" key={i}><b>Set {i+1}</b><label>Reps<input aria-label={`${item.name} set ${i+1} reps`} type="number" min="0" value={item.actualSets[i]?.reps??""} onChange={e=>updateSet(item,i,"reps",e.target.value)}/></label><label>Weight (kg)<input aria-label={`${item.name} set ${i+1} weight`} type="number" min="0" step="0.5" value={item.actualSets[i]?.weight??""} onChange={e=>updateSet(item,i,"weight",e.target.value)}/></label></div>)}</div></article>)}</section><p className="module-disclaimer">Workout templates and set logs are saved in this browser. GIFs display larger previews when the URL points directly to an image file.</p><AnimatePresence>{dialog&&<><motion.button className="scrim" aria-label="Close workout editor" onClick={()=>setDialog(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.section className="food-dialog exercise-dialog" role="dialog" aria-modal="true" aria-labelledby="weekly-exercise-title" initial={{opacity:0,scale:.97,y:8}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:.98}}><div className="dialog-head"><div><span className="eyebrow">WEEKLY TEMPLATE · {dayNames[weekKeys.indexOf(day as typeof weekKeys[number])].toUpperCase()}</span><h2 id="weekly-exercise-title">{editing?"Edit exercise":"Add an exercise"}</h2><p>Set the target and optionally link a demo or GIF.</p></div><button className="icon-btn" aria-label="Close" onClick={()=>setDialog(false)}><X size={18}/></button></div><label className="field-label">Exercise name<input autoFocus value={draft.name} placeholder="e.g. Dumbbell chest press" onChange={e=>setDraft({...draft,name:e.target.value})}/></label><div className="nutrition-inputs"><label className="field-label">Number of sets<input type="number" min="1" max="20" value={draft.sets} onChange={e=>setDraft({...draft,sets:Math.max(1,Number(e.target.value))})}/></label><label className="field-label">Target reps<input value={draft.reps} onChange={e=>setDraft({...draft,reps:e.target.value})}/></label></div><label className="field-label">Demo video, article, or GIF URL <span className="optional-label">optional</span><input type="url" value={draft.mediaUrl} placeholder="https://…" onChange={e=>setDraft({...draft,mediaUrl:e.target.value})}/></label>{draft.mediaUrl.match(/\.(gif|png|jpe?g|webp)(\?.*)?$/i)&&<div className="gif-preview"><img src={draft.mediaUrl} alt="Exercise GIF preview"/></div>}<div className="dialog-actions"><button className="secondary-btn" onClick={()=>setDialog(false)}>Cancel</button><button className="primary-btn" onClick={save}>Save exercise <ArrowRight size={15}/></button></div></motion.section></>}</AnimatePresence></>;
}

function WeightTracker({entries,currentWeight,onNew,onEdit}:{entries:WeightLog[];currentWeight:number;onNew:()=>void;onEdit:(entry?:WeightLog)=>void}){
  const sorted=[...entries].sort((a,b)=>a.date.localeCompare(b.date));const recent=sorted.slice(-7);const average=recent.length?recent.reduce((sum,x)=>sum+x.weight,0)/recent.length:currentWeight;
  return <><div className="weight-feature panel"><div><span className="eyebrow">PERSONAL WEIGHT HISTORY</span><h2>{currentWeight.toFixed(1)} <small>kg</small></h2><p>7-entry average: {average.toFixed(1)} kg</p><small>BMR and sedentary TDEE update using your latest logged weight.</small></div><div className="weight-feature-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={recent.map(x=>({day:x.date,value:x.weight}))}><Area type="monotone" dataKey="value" stroke="var(--blue)" strokeWidth={2} fill="url(#weightGradient2)"/><defs><linearGradient id="weightGradient2" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--blue)" stopOpacity={.25}/><stop offset="100%" stopColor="var(--blue)" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="day" hide/></AreaChart></ResponsiveContainer></div></div><section className="panel module-panel"><div className="panel-heading"><div><h3>Weight entries</h3><p>Choose any date to add or correct a past weigh-in.</p></div><button className="primary-btn" onClick={onNew}><Plus size={15}/> Log weight</button></div>{sorted.length===0?<Empty message="Start with your current weight. Each entry updates your energy calculation." icon={Weight}/>:sorted.slice().reverse().map(entry=><div className="weight-log-row" key={entry.id}><div><b>{entry.weight.toFixed(1)} kg</b><small>{new Date(`${entry.date}T12:00:00`).toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short",year:"numeric"})}</small></div><button className="secondary-btn" onClick={()=>onEdit(entry)}>Edit</button></div>)}</section></>;
}

type PlannerEvent={id:string;title:string;date:string;time:string;category:string};
function PlannerManager({events,setEvents,addRequest}:{events:PlannerEvent[];setEvents:React.Dispatch<React.SetStateAction<PlannerEvent[]>>;addRequest:number}){
  const [dialog,setDialog]=useState(false);const [editing,setEditing]=useState<string|null>(null);const blank={title:"",date:localDay(),time:"09:00",category:"Personal"};const [draft,setDraft]=useState(blank);
  const openNew=()=>{setEditing(null);setDraft({...blank,date:localDay()});setDialog(true)};useEffect(()=>{if(addRequest>0)openNew()},[addRequest]);
  const save=()=>{if(!draft.title.trim()||!draft.date)return;const entry={...draft,id:editing??crypto.randomUUID(),title:draft.title.trim()};setEvents(all=>editing?all.map(x=>x.id===editing?entry:x):[...all,entry]);setDialog(false)};
  const remove=(id:string)=>setEvents(all=>all.filter(x=>x.id!==id));const today=localDay();const ordered=[...events].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
  return <><section className="panel module-panel"><div className="panel-heading"><div><h3>Your events</h3><p>Add and manage reminders on any day.</p></div><button className="primary-btn" onClick={openNew}><Plus size={15}/> Add event</button></div>{ordered.length===0?<Empty message="Your planner is ready. Add a workout, reminder, or personal event." icon={CalendarDays}/>:ordered.map(event=><div className="planner-event" key={event.id}><span className="event-date"><strong>{new Date(`${event.date}T12:00:00`).getDate()}</strong><small>{new Date(`${event.date}T12:00:00`).toLocaleDateString("en-IN",{month:"short"}).toUpperCase()}</small></span><div className="event-info"><strong>{event.title}</strong><span>{event.date===today?"Today":new Date(`${event.date}T12:00:00`).toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short"})} · {event.time} · {event.category}</span></div><button className="secondary-btn" onClick={()=>{setEditing(event.id);setDraft({title:event.title,date:event.date,time:event.time,category:event.category});setDialog(true)}}>Edit</button><button className="delete-btn" aria-label={`Delete ${event.title}`} onClick={()=>remove(event.id)}><X size={15}/></button></div>)}</section><AnimatePresence>{dialog&&<><motion.button className="scrim" aria-label="Close event editor" onClick={()=>setDialog(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.section className="food-dialog" role="dialog" aria-modal="true" aria-labelledby="event-title" initial={{opacity:0,scale:.97,y:8}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:.98}}><div className="dialog-head"><div><span className="eyebrow">PLANNER · PERSONAL EVENT</span><h2 id="event-title">{editing?"Edit event":"Add an event"}</h2><p>Choose when it happens and what kind of reminder it is.</p></div><button className="icon-btn" aria-label="Close" onClick={()=>setDialog(false)}><X size={18}/></button></div><label className="field-label">Event name<input autoFocus value={draft.title} placeholder="e.g. Meal prep" onChange={e=>setDraft({...draft,title:e.target.value})}/></label><div className="nutrition-inputs"><label className="field-label">Date<input type="date" value={draft.date} onChange={e=>setDraft({...draft,date:e.target.value})}/></label><label className="field-label">Time<input type="time" value={draft.time} onChange={e=>setDraft({...draft,time:e.target.value})}/></label></div><label className="field-label">Category<input value={draft.category} placeholder="Personal" onChange={e=>setDraft({...draft,category:e.target.value})}/></label><div className="dialog-actions"><button className="secondary-btn" onClick={()=>setDialog(false)}>Cancel</button><button className="primary-btn" onClick={save}>{editing?"Save changes":"Add event"} <ArrowRight size={15}/></button></div></motion.section></>}</AnimatePresence></>;
}

function CoachCalculator({profile,date,caloriesConsumed,onApply,goWorkouts}:{profile:EnergyProfile;date:string;caloriesConsumed:number;onApply:(date:string,burn:number,target:{calories:number;protein:number;carbs:number;fats:number})=>void;goWorkouts:()=>void}){
  const [goal,setGoal]=useState<"fat-loss"|"maintain"|"muscle">("fat-loss");const [burn,setBurn]=useState(0);const [intake,setIntake]=useState(caloriesConsumed);const [trainingDays,setTrainingDays]=useState(3);const result=calculateEnergy(profile,intake,burn);const target=Math.round(result.sedentaryTdee+(goal==="fat-loss"?-500:goal==="muscle"?200:0));const protein=Math.round(profile.weightKg*1.6);const fats=Math.round(profile.weightKg*.8);const carbs=Math.max(0,Math.round((target-protein*4-fats*9)/4));const split:Record<number,string[]>={2:["Full body A","Full body B"],3:["Full body · A","Full body · B","Full body · C"],4:["Upper body","Lower body","Upper body","Lower body"],5:["Push","Pull","Legs","Upper body","Lower body"]};
  const apply=()=>onApply(date,burn,{calories:target,protein,carbs,fats});
  return <div className="coach-tools"><section className="coach-card"><span className="coach-symbol"><Sparkles size={20}/></span><span className="eyebrow">LOCAL COACH CALCULATOR · NO AI KEY</span><h2>Make your energy numbers useful.</h2><p>This uses your profile and the Mifflin–St Jeor formula. It works offline; AI is not connected.</p><div className="coach-fields"><label className="field-label">Goal<select value={goal} onChange={e=>setGoal(e.target.value as typeof goal)}><option value="fat-loss">Fat loss · modest starting target</option><option value="maintain">Maintain weight</option><option value="muscle">Build muscle · small surplus</option></select></label><div className="nutrition-inputs"><label className="field-label">Calories eaten<input type="number" min="0" value={intake} onChange={e=>setIntake(Math.max(0,Number(e.target.value)))}/></label><label className="field-label">Exercise burn<input type="number" min="0" value={burn} onChange={e=>setBurn(Math.max(0,Number(e.target.value)))}/></label></div></div><div className="coach-result-grid"><div><small>BMR</small><b>{fmt(result.bmr)} kcal</b></div><div><small>SEDENTARY TDEE</small><b>{fmt(result.sedentaryTdee)} kcal</b></div><div><small>TOTAL BURN</small><b>{fmt(result.totalBurn)} kcal</b></div><div><small>DEFICIT</small><b>{fmt(result.deficit)} kcal</b></div><div><small>FAT LOSS ESTIMATE</small><b>{result.fatLossGrams.toFixed(0)} g/day</b></div><div><small>WEEKLY ESTIMATE</small><b>{result.weeklyFatLossKg.toFixed(2)} kg</b></div></div><div className="macro-recommendation"><strong>Starting daily nutrition target · {target.toLocaleString()} kcal</strong><span>Protein {protein} g · Carbs {carbs} g · Fat {fats} g</span><small>Macro guide is a general estimate based on current body weight; adjust to your preferences.</small></div><div className="dialog-actions"><button className="secondary-btn" onClick={apply}>Apply to calorie day</button><button className="primary-btn" onClick={apply}>Open {date} calorie day <ArrowRight size={15}/></button></div><small className="coach-note">Fat-loss figures are mathematical estimates, not a prediction of scale change. Update your weight log to refresh BMR and TDEE.</small></section><section className="panel module-panel coach-workout-note"><div className="panel-heading"><div><h3>Weekly workout structure</h3><p>A starting split you can build into the repeating day-by-day planner.</p></div><button className="secondary-btn" onClick={goWorkouts}>Open workout planner <ArrowRight size={14}/></button></div><label className="field-label">Training days per week<select value={trainingDays} onChange={e=>setTrainingDays(Number(e.target.value))}>{[2,3,4,5].map(n=><option key={n} value={n}>{n} days</option>)}</select></label><div className="coach-split">{split[trainingDays].map((name,i)=><span key={`${name}-${i}`}><b>Day {i+1}</b>{name}</span>)}</div><p>This is a simple template suggestion. Add exercises, media, target sets, and logged reps in the workout planner.</p></section></div>;
}
